// =============================================================================
// VELO Frontend -- MyBookingsView Screen Tests (T8, PROMPT №431)
// =============================================================================
//
// First screen test in the repo. Generated by probekit-screen-test; the idiom
// is copied from the existing 23 test files, not invented -- createApp +
// happy-dom (no @vue/test-utils, per MethodTaxonomyPicker.test.ts:19-20), real
// Pinia + mocked API wrapper (per stores/bookings.test.ts:21-32), vue-router
// mocked rather than built (guards.test.ts never builds one either).
//
// PATTERN A (query-backed, FE-166): the list lives in the Pinia Colada cache
// (useMyBookings, an infinite query), so the seam is @/api/bookings -- the
// wrapper the query calls. The cache is REAL; only the network boundary is
// faked.
//
// The mount needs Pinia AND Colada inside it (coladaOptions, as app.ts). The
// same pinia instance goes to setActivePinia AND app.use; two instances would
// mean two caches -- a re-visit would not see the first visit's list, and the
// B30 test below would pass while proving nothing.
//
// TIME IS PINNED (vi.setSystemTime). The screen reads Date.now()/new Date() in
// upcomingRank/isToday/isTomorrow/badgeFor, so the today/tomorrow badges
// (i18n:user.screens.myBookings.status.today /
// i18n:user.screens.myBookings.status.tomorrow) and the sort
// order are wall-clock dependent; fixtures below are literals relative to the
// frozen instant, and practice.timezone is 'UTC' so Intl's calendar-date
// comparison can't drift across the runner's local zone.
// =============================================================================

import { createTestI18n } from '@/locales/testing'
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { createApp, nextTick, type App } from 'vue'
import { setActivePinia, createPinia, type Pinia } from 'pinia'
import { PiniaColada } from '@pinia/colada'
import { coladaOptions } from '@/composables/queries/setup'
import MyBookingsView from '@/views/user/MyBookingsView.vue'
import * as bookingsApi from '@/api/bookings'
import { ApiResponseError } from '@/api/client'
import { useAuthStore } from '@/stores/auth'
import type { BookingWithPracticeResponse, UserResponse } from '@/api/types'

vi.mock('@/api/bookings')

const push = vi.fn()
const back = vi.fn()
vi.mock('vue-router', () => ({
  useRouter: () => ({ push, back }),
}))

// A failed show-more tap (i18n:common.showMore) toasts (.vue:onLoadMore) --
// the toast IS the entire user-facing half of that path, so it has to be a
// real assertion seam.
const toastError = vi.fn()
vi.mock('@/composables/useToast', () => ({
  useToast: () => ({ error: toastError, success: vi.fn(), info: vi.fn() }),
}))

const NOW = new Date('2026-07-20T12:00:00Z')

function booking(
  id: string,
  overrides: Partial<BookingWithPracticeResponse> = {},
  practice: Partial<BookingWithPracticeResponse['practice']> = {},
): BookingWithPracticeResponse {
  return {
    id,
    practice_id: `practice_${id}`,
    user_id: 'user_1',
    status: 'confirmed',
    purchase_id: null,
    cancelled_at: null,
    cancellation_reason: null,
    joined_at: null,
    left_at: null,
    checkin_skipped: false,
    created_at: '2026-07-01T00:00:00Z',
    updated_at: null,
    has_feedback: false,
    has_checkin: false,
    has_reflection: false,
    ...overrides,
    practice: {
      id: `practice_${id}`,
      title: `Practice ${id}`,
      practice_type: 'live',
      status: 'scheduled',
      scheduled_at: '2026-07-25T10:00:00Z',
      duration_minutes: 60,
      timezone: 'UTC',
      master_id: 'master_1',
      master_name: 'Мастер',
      direction: null,
      is_free: true,
      price_cents: 0,
      currency: 'RUB',
      ...practice,
    } as BookingWithPracticeResponse['practice'],
  }
}

function page(items: BookingWithPracticeResponse[], total = items.length) {
  return { items, total, limit: 20, offset: 0 }
}

// SW3: the viewer's profile timezone, distinct from every fixture's own
// practice.timezone (default 'UTC') -- used to prove isToday/isTomorrow/
// badgeFor read the VIEWER's tz, not the practice's own.
const VIEWER_TZ = 'Europe/Moscow' // UTC+3

function user(overrides: Partial<UserResponse> = {}): UserResponse {
  return {
    id: 'user_1',
    telegram_id: 1,
    role: 'user',
    first_name: 'Аня',
    last_name: null,
    avatar_url: null,
    timezone: VIEWER_TZ,
    language: 'ru',
    is_active: true,
    balance_cents: 0,
    created_at: '2026-01-01T00:00:00Z',
    last_login_at: null,
    onboarding_completed: true,
    master_onboarding_completed: false,
    phone: null,
    bio: null,
    email: null,
    role_switch: null,
    birth_date: null,
    goals: [],
    goals_custom: null,
    ...overrides,
  }
}

let app: App | null = null
let host: HTMLElement | null = null
let pinia: Pinia

function mount(): HTMLElement {
  host = document.createElement('div')
  document.body.appendChild(host)
  app = createApp(MyBookingsView).use(createTestI18n())
  app.use(pinia).use(PiniaColada, coladaOptions)
  app.mount(host)
  return host
}

// useMyBookings (Colada) -> fetch -> awaited getMyBookings + the entry's
// state update + the re-render; a load-more adds the page merge. Ticks plus
// one macrotask, as composables/queries/*.test.ts flush.
async function flush(): Promise<void> {
  for (let i = 0; i < 6; i++) await nextTick()
  // Under fake timers a real setTimeout never fires: advance the clock by 0.
  if (vi.isFakeTimers()) await vi.advanceTimersByTimeAsync(0)
  else await new Promise((resolve) => setTimeout(resolve, 0))
  await nextTick()
}

function text(): string {
  return host?.textContent ?? ''
}

beforeEach(() => {
  vi.setSystemTime(NOW)
  pinia = createPinia()
  setActivePinia(pinia)
  vi.mocked(bookingsApi.getMyBookings).mockReset().mockResolvedValue(page([]))
  useAuthStore().user = user()
  push.mockReset()
  back.mockReset()
})

afterEach(() => {
  app?.unmount()
  host?.remove()
  app = null
  host = null
  vi.useRealTimers()
  vi.clearAllMocks()
})

describe('MyBookingsView', () => {
  describe('state ladder', () => {
    it('initial load: shows the loader while the first page is in flight', async () => {
      // Never resolves -> the list stays loading with nothing to show, which is
      // exactly the :pending guard of the VLoadingSwap.
      vi.mocked(bookingsApi.getMyBookings).mockReturnValue(new Promise(() => {}))
      mount()
      await flush()

      expect(host?.querySelector('.bookings__loader')).not.toBeNull()
      expect(text()).not.toContain('Бронирований нет')
    })

    it('slow first page: the skeleton, once seen, stays its 450 ms minimum, then the list replaces it', async () => {
      vi.useFakeTimers()
      try {
        let resolvePage!: (v: ReturnType<typeof page>) => void
        vi.mocked(bookingsApi.getMyBookings).mockReturnValue(
          new Promise((resolve) => {
            resolvePage = resolve
          }),
        )
        mount()
        await flush()
        await vi.advanceTimersByTimeAsync(320) // past the 300 ms delay: seen

        resolvePage(page([booking('b1', {}, { title: 'Утренняя практика' })]))
        await flush()
        // The data is here, but the placeholder holds its minimum: no blink.
        expect(host?.querySelector('.bookings__loader')).not.toBeNull()
        expect(text()).not.toContain('Утренняя практика')

        await vi.advanceTimersByTimeAsync(450)
        await flush()
        expect(text()).toContain('Утренняя практика')
      } finally {
        vi.useRealTimers()
      }
    })

    it('error: shows the error state with the catalog phrase of the backend code (ADR)', async () => {
      // FE-166 (ADR, one error convention): the query rejects with the raw
      // error and the screen words it -- extractApiError looks e.code up in
      // the errors catalog. The backend's raw detail never reaches the DOM.
      vi.mocked(bookingsApi.getMyBookings).mockRejectedValue(
        new ApiResponseError(404, 'Bookings not found', 'not_found'),
      )
      mount()
      await flush()

      expect(text()).toContain('Ошибка загрузки')
      expect(text()).toContain('Запрошенный ресурс не найден')
      expect(text()).not.toContain('Bookings not found')
    })

    it('error: a failure with no backend code reads as the list fallback, never e.message', async () => {
      // Before FE-166 the rung showed e.message verbatim -- an English or
      // technical string for a network failure.
      vi.mocked(bookingsApi.getMyBookings).mockRejectedValue(new Error('Failed to fetch'))
      mount()
      await flush()

      expect(text()).toContain('Не удалось загрузить бронирования')
      expect(text()).not.toContain('Failed to fetch')
    })

    it('error retry: the button re-fetches the list', async () => {
      vi.mocked(bookingsApi.getMyBookings).mockRejectedValue(new Error('Сервис недоступен'))
      mount()
      await flush()
      vi.mocked(bookingsApi.getMyBookings).mockClear()

      const retry = Array.from(host?.querySelectorAll('button') ?? []).find((b) =>
        b.textContent?.includes('Попробовать снова'),
      )
      expect(retry).toBeDefined()
      retry?.click()
      await flush()

      expect(bookingsApi.getMyBookings).toHaveBeenCalled()
    })

    it('empty: shows the empty state when the page is genuinely empty', async () => {
      mount()
      await flush()

      expect(text()).toContain('Бронирований нет')
      expect(host?.querySelector('.bookings__loader')).toBeNull()
    })

    it('content: renders what the server actually returned', async () => {
      vi.mocked(bookingsApi.getMyBookings).mockResolvedValue(
        page([booking('b1', {}, { title: 'Утренняя практика' })]),
      )
      mount()
      await flush()

      expect(text()).toContain('Утренняя практика')
      expect(text()).not.toContain('Бронирований нет')
    })

    it('a load-more failure keeps content visible AND tells the user (№442)', async () => {
      // Half of this was already true and half of it was the bug. The list
      // surviving is the guard (`failed` only with nothing to show) doing its
      // job. But until №442 the failure was NEVER surfaced -- the error was read
      // nowhere outside that guarded rung, so the tap did nothing and nothing said why -- the silent
      // variant the whole session has been chasing. The toast is the other half;
      // drop it and this test fails.
      vi.mocked(bookingsApi.getMyBookings).mockResolvedValue(
        page([booking('b1', {}, { title: 'Утренняя практика' })], 40),
      )
      mount()
      await flush()

      vi.mocked(bookingsApi.getMyBookings).mockRejectedValue(new Error('Сеть отвалилась'))
      const more = Array.from(host?.querySelectorAll('button') ?? []).find((b) =>
        b.textContent?.includes('Показать ещё'),
      )
      expect(more).toBeDefined()
      more?.click()
      await flush()

      expect(text()).toContain('Утренняя практика')
      expect(text()).not.toContain('Ошибка загрузки')
      // ADR: worded by the screen (no backend code -> the list fallback).
      expect(toastError).toHaveBeenCalledWith('Не удалось загрузить бронирования')
    })

    it('a load-more failure never raises the full error rung, and the list stays usable', async () => {
      // The root fix (№442), now structural in Colada: a failed later page keeps
      // the loaded pages, so `failed` (nothing to show) stays false -- the rung
      // cannot appear over a list, whichever screen reads it. And the next tap
      // loads the page that failed.
      vi.mocked(bookingsApi.getMyBookings).mockResolvedValue(
        page([booking('b1', {}, { title: 'Утренняя практика' })], 40),
      )
      mount()
      await flush()

      vi.mocked(bookingsApi.getMyBookings).mockRejectedValue(new Error('Сеть отвалилась'))
      Array.from(host?.querySelectorAll('button') ?? [])
        .find((b) => b.textContent?.includes('Показать ещё'))
        ?.click()
      await flush()

      expect(text()).not.toContain('Ошибка загрузки')
      expect(text()).toContain('Утренняя практика')

      vi.mocked(bookingsApi.getMyBookings).mockResolvedValue(
        page([booking('b2', {}, { title: 'Вечерняя практика' })], 40),
      )
      Array.from(host?.querySelectorAll('button') ?? [])
        .find((b) => b.textContent?.includes('Показать ещё'))
        ?.click()
      await flush()

      expect(text()).toContain('Утренняя практика')
      expect(text()).toContain('Вечерняя практика')
      expect(vi.mocked(bookingsApi.getMyBookings).mock.calls.at(-1)).toEqual([undefined, 20, 1])
    })

    it('an INITIAL-load failure raises the rung, not a toast', async () => {
      // The other side of the split: it must not become a blanket toast that
      // silences the first page too. Without this, toasting everything would
      // pass every other test in this file.
      vi.mocked(bookingsApi.getMyBookings).mockRejectedValue(new Error('Сервис недоступен'))
      mount()
      await flush()

      expect(text()).toContain('Ошибка загрузки')
      expect(text()).toContain('Не удалось загрузить бронирования')
      expect(toastError).not.toHaveBeenCalled()
    })
  })

  describe('grouping and badges', () => {
    it('splits upcoming from past and badges each by its own rule', async () => {
      vi.mocked(bookingsApi.getMyBookings).mockResolvedValue(
        page([
          // ended 10 days ago, attended -> the past section
          // (i18n:user.screens.myBookings.tabs.past) + the done badge
          // (i18n:user.screens.myBookings.done)
          booking('past1', { status: 'attended' }, { scheduled_at: '2026-07-10T10:00:00Z' }),
          // later today -> the upcoming section
          // (i18n:user.screens.myBookings.tabs.upcoming) + the today badge
          // (i18n:user.screens.myBookings.status.today)
          booking('today1', {}, { scheduled_at: '2026-07-20T18:00:00Z' }),
          // tomorrow -> the upcoming section + the tomorrow badge
          // (i18n:user.screens.myBookings.status.tomorrow)
          booking('tom1', {}, { scheduled_at: '2026-07-21T10:00:00Z' }),
        ]),
      )
      mount()
      await flush()

      expect(text()).toContain('Предстоящие')
      expect(text()).toContain('Прошедшие')
      expect(text()).toContain('Сегодня')
      expect(text()).toContain('Завтра')
      expect(text()).toContain('Завершена')
    })

    it('a confirmed booking whose practice already ended is past and badged «Подсчет», not an upcoming badge', async () => {
      // MyBookingsView.vue:198-201: the backend keeps confirmed until finalize
      // (settlement grace window), so status alone would mis-file it as upcoming
      // and paint a misleading today badge
      // (i18n:user.screens.myBookings.status.today) on a practice that is
      // over.
      // AT-2 (PROMPT №585): it's ALSO not silent any more -- a Zoom-tracked
      // practice awaiting its attendance report gets an honest "still being
      // decided" badge instead of no badge at all.
      vi.mocked(bookingsApi.getMyBookings).mockResolvedValue(
        page([
          booking(
            'ended',
            { status: 'confirmed' },
            { scheduled_at: '2026-07-20T09:00:00Z', duration_minutes: 60 },
          ),
        ]),
      )
      mount()
      await flush()

      expect(text()).toContain('Прошедшие')
      expect(text()).not.toContain('Предстоящие')
      expect(text()).not.toContain('Сегодня')
      expect(text()).not.toContain('В эфире')
      expect(text()).toContain('Подсчет')
    })

    it('the first visit sends ONE request: the B30 refetch joins the first load', async () => {
      mount()
      await flush()

      expect(bookingsApi.getMyBookings).toHaveBeenCalledTimes(1)
    })

    it('B30: a re-visit refetches instead of reusing a stale list -- the badge advances past «Подсчет»', async () => {
      // First visit: the practice just ended, the Zoom report hasn't ripened
      // yet -- confirmed + ended reads as "still being decided".
      vi.mocked(bookingsApi.getMyBookings).mockResolvedValueOnce(
        page([
          booking(
            'b1',
            { status: 'confirmed' },
            { scheduled_at: '2026-07-20T09:00:00Z', duration_minutes: 60 },
          ),
        ]),
      )
      mount()
      await flush()
      expect(text()).toContain('Подсчет')

      // Leave and come back once the report has ripened: same booking, now
      // decided. The pre-B30 fetchMyBookings() would have skipped this fetch
      // entirely because the list was already non-empty, leaving the stale
      // counting badge (i18n:user.screens.myBookings.status.counting)
      // showing forever.
      vi.mocked(bookingsApi.getMyBookings).mockResolvedValueOnce(
        page([
          booking(
            'b1',
            { status: 'attended' },
            { scheduled_at: '2026-07-20T09:00:00Z', duration_minutes: 60 },
          ),
        ]),
      )
      app?.unmount()
      host?.remove()
      mount()
      await flush()

      expect(text()).toContain('Завершена')
      expect(text()).not.toContain('Подсчет')
    })

    it('a practice in progress is upcoming and badged «В эфире»', async () => {
      vi.mocked(bookingsApi.getMyBookings).mockResolvedValue(
        page([
          booking(
            'live',
            { status: 'confirmed' },
            { scheduled_at: '2026-07-20T11:30:00Z', duration_minutes: 60 },
          ),
        ]),
      )
      mount()
      await flush()

      expect(text()).toContain('Предстоящие')
      expect(text()).toContain('В эфире')
    })

    it("SW3: badge uses the VIEWER profile timezone, not the practice's own -- distinguishing fixture", async () => {
      // Same distinguishing instant/tz pair as CalendarView's SW2 test: 20:00
      // UTC on the 20th (after NOW=12:00Z, not live, not ended). In the
      // VIEWER's Moscow (UTC+3) that's 23:00 on the 20th -- same calendar day
      // as NOW there (15:00) -- so the correct badge is today
      // (i18n:user.screens.myBookings.status.today). In the
      // practice's OWN tz (Asia/Yekaterinburg, UTC+5, no DST) the same instant
      // is 01:00 on the 21st while NOW there is 17:00 on the 20th, so the OLD
      // buggy behaviour (reading b.practice.timezone) badges it tomorrow
      // (i18n:user.screens.myBookings.status.tomorrow)
      // instead -- a genuinely different label, not a coincidental match.
      vi.mocked(bookingsApi.getMyBookings).mockResolvedValue(
        page([
          booking(
            'tzcheck',
            { status: 'confirmed' },
            {
              scheduled_at: '2026-07-20T20:00:00Z',
              duration_minutes: 60,
              timezone: 'Asia/Yekaterinburg',
            },
          ),
        ]),
      )
      mount()
      await flush()

      expect(text()).toContain('Сегодня')
      expect(text()).not.toContain('Завтра')
    })

    // SW9 (found while grepping for other sites during PROMPT №577's
    // comparison task): isTomorrow's OWN `tomorrow.setDate(getDate()+1)` is
    // device-local Date math, unlike the fix applied to utils/format.ts's
    // formatDateShort/dayLabelOf. Fixing SW3's "which timezone to compare
    // in" left this local mutation in place -- on a day the DEVICE's own OS
    // timezone crosses a DST transition, it does not land exactly +24h,
    // which can resolve to the wrong calendar day once compared against the
    // viewer's timezone, independent of whether the viewer's timezone itself
    // observes DST.
    it('SW9: "Завтра" is unaffected by the DEVICE\'s own DST transition', async () => {
      vi.stubEnv('TZ', 'America/New_York') // US spring-forward 2026: Mar 8.
      try {
        // "Now" = Mar 7, 8pm EST (the evening before the device's own DST
        // jump). setDate(getDate()+1) resolves to Mar 8, 8pm -- by then EDT
        // has started, so that instant is only +23h from "now", not +24h.
        vi.setSystemTime(new Date('2026-03-08T01:00:00.000Z'))
        // Viewer profile tz Cape Verde (UTC-1, no DST, ever) straddles a
        // local midnight between the OLD (buggy, +23h) and the CORRECT
        // (+24h) "tomorrow" instant -- same fixture as format.test.ts's SW9
        // coverage for formatDateShort.
        useAuthStore().user = user({ timezone: 'Atlantic/Cape_Verde' })

        vi.mocked(bookingsApi.getMyBookings).mockResolvedValue(
          page([
            booking(
              'dstcheck',
              { status: 'confirmed' },
              { scheduled_at: '2026-03-09T12:00:00Z', duration_minutes: 60, timezone: 'UTC' },
            ),
          ]),
        )
        mount()
        await flush()

        expect(text()).toContain('Завтра')
      } finally {
        vi.unstubAllEnvs()
        vi.setSystemTime(NOW)
      }
    })
  })

  describe('navigation', () => {
    it('tapping a booking opens the practice detail by practice_id, not booking id', async () => {
      // MyBookingsView.vue:213-218: the dedicated booking-detail screen is gone;
      // routing by the wrong id here would 404 at runtime.
      vi.mocked(bookingsApi.getMyBookings).mockResolvedValue(
        page([booking('b1', { practice_id: 'practice_42' }, { title: 'Утренняя практика' })]),
      )
      mount()
      await flush()

      const card = host?.querySelector<HTMLElement>('.bookings__list > *')
      expect(card).not.toBeNull()
      card?.click()
      await flush()

      expect(push).toHaveBeenCalledWith({
        name: 'practice-detail',
        params: { id: 'practice_42' },
      })
    })
  })
})
